import{_ as n,c as e,o as s,ag as t}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Setting up Maubot","description":"","frontmatter":{"title":"Setting up Maubot"},"headers":[],"relativePath":"general/setting-up-maubot.md","filePath":"general/setting-up-maubot.md","lastUpdated":null}'),i={name:"general/setting-up-maubot.md"};function r(o,a,p,l,u,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="setting-up-maubot" tabindex="-1">Setting up Maubot <a class="header-anchor" href="#setting-up-maubot" aria-label="Permalink to &quot;Setting up Maubot&quot;">​</a></h1><h2 id="maubot-in-the-community" tabindex="-1">Maubot in the Community <a class="header-anchor" href="#maubot-in-the-community" aria-label="Permalink to &quot;Maubot in the Community&quot;">​</a></h2><p>Using the following Plugins:</p><ul><li><p><a href="https://github.com/gitayam/matrix-to-discourse" target="_blank" rel="noreferrer">https://github.com/gitayam/matrix-to-discourse</a></p></li><li><p><a href="https://github.com/ggogel/SocialMediaDownloadMaubot" target="_blank" rel="noreferrer">https://github.com/ggogel/SocialMediaDownloadMaubot</a></p></li><li><p><a href="https://github.com/maubot/reminder" target="_blank" rel="noreferrer">https://github.com/maubot/reminder</a></p></li><li><p><a href="https://github.com/maubot/reactbot" target="_blank" rel="noreferrer">https://github.com/maubot/reactbot</a></p></li></ul><p>Some of these plugins have been modified from the source to fit the community&#39;s needs.</p><h3 id="maubot-documentation" tabindex="-1">Maubot Documentation <a class="header-anchor" href="#maubot-documentation" aria-label="Permalink to &quot;Maubot Documentation&quot;">​</a></h3><p>Maubot is used for moderation and management tasks within Matrix environments. Below are useful resources and steps for setting up and managing Maubot.</p><p><strong>GitHub Repository and Project Documentation</strong></p><ul><li><p><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/master/docs/configuring-playbook-bot-maubot.md" target="_blank" rel="noreferrer">Maubot Configuration Documentation on GitHub</a></p></li><li><p><a href="https://docs.mau.fi/maubot/usage/basic.html" target="_blank" rel="noreferrer">Official Maubot Project Documentation</a></p></li></ul><p><strong>Plugins Available</strong></p><ul><li>Find available plugins <a href="https://plugins.mau.bot" target="_blank" rel="noreferrer">here</a>.</li></ul><p><strong>Admin Dashboard</strong></p><ul><li>The Maubot admin dashboard can be accessed at: <a href="https://matrix.irregularchat.com/_matrix/maubot/" target="_blank" rel="noreferrer">matrix.irregularchat.com/_matrix/maubot/</a>.</li></ul><h3 id="maubot-access-token-with-sso" tabindex="-1">Maubot Access Token with SSO <a class="header-anchor" href="#maubot-access-token-with-sso" aria-label="Permalink to &quot;Maubot Access Token with SSO&quot;">​</a></h3><p>To obtain a Maubot access token using SSO, follow these steps: Reference: <a href="https://docs.mau.fi/maubot/usage/cli/auth.html" target="_blank" rel="noreferrer">Maubot Authentication Documentation</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>#Launch an interactive shell in the Maubot container</span></span>
<span class="line"><span>sudo docker exec -it matrix-bot-maubot /bin/sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>HOMESERVER_URL=&quot;https://matrix.irregularchat.com&quot;</span></span>
<span class="line"><span>USERNAME=&quot;maubotuser&quot;</span></span>
<span class="line"><span>#You must login before authenticating. This is logging in to the maubot portal</span></span>
<span class="line"><span>mbc login -u &quot;$USERNAME&quot; -s &quot;$HOMESERVER_URL&quot; -a homeserver -p passwordHERE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. now while authenticated, login to the user account</span></span>
<span class="line"><span>1. If you have an SSO for the user</span></span>
<span class="line"><span>DOMAIN=&quot;https://matrix.irregularchat.com&quot;</span></span>
<span class="line"><span>HOMESERVER_URL=&quot;https://matrix.irregularchat.com&quot;</span></span>
<span class="line"><span>USERNAME=&quot;bot.user&quot;</span></span>
<span class="line"><span>mbc login -u $USERNAME -s $HOMESERVER_URL -a $DOMAIN -p &quot;passwordHERE&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. now while authenticated, login to the user account</span></span>
<span class="line"><span>1. If you have an SSO for the user</span></span>
<span class="line"><span>DOMAIN=&quot;https://matrix.irregularchat.com&quot;</span></span>
<span class="line"><span>HOMESERVER_URL=&quot;https://matrix.irregularchat.com&quot;</span></span>
<span class="line"><span>USERNAME=&quot;bot.user&quot;</span></span>
<span class="line"><span>mbc auth -s &quot;$HOMESERVER_URL&quot; -h &quot;$DOMAIN&quot; -o --update-client -u &quot;$USERNAME&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>The output should look like this: <code>Opening http://matrix-nginx-proxy:12080/_matrix/client/v3/login/sso/redirect?redirectUrl=https://matrix.irregularchat.com/_matrix/maubot/v1/client/auth_external_sso/complete/randomhere</code></p><h2 id="open-a-browser-and-replace-http-matrix-nginx-proxy-12080-with-https-matrix-irregularchat-com" tabindex="-1">Open a browser and replace <code>http://matrix-nginx-proxy:12080</code> with <code>https://matrix.irregularchat.com</code>. <a class="header-anchor" href="#open-a-browser-and-replace-http-matrix-nginx-proxy-12080-with-https-matrix-irregularchat-com" aria-label="Permalink to &quot;Open a browser and replace \`http://matrix-nginx-proxy:12080\` with \`https://matrix.irregularchat.com\`.&quot;">​</a></h2><ol start="2"><li>Log in using Single Sign-On (SSO).</li></ol><h3 id="packaging-the-plugin" tabindex="-1">Packaging the Plugin <a class="header-anchor" href="#packaging-the-plugin" aria-label="Permalink to &quot;Packaging the Plugin&quot;">​</a></h3><p>To package a plugin for Maubot, use the following command:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Inside the cloned git directory</span></span>
<span class="line"><span>zip -9r plugin-name.mbp *</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>[Management]</p>`,26)])])}const m=n(i,[["render",r]]);export{h as __pageData,m as default};
